insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_aas_v1'
from (values
('113.51.c.1.A',3,'The Kingdom of Kush, which built pyramids at Meroë, was located in what region?','["Along the Nile River south of Egypt", "Western Europe", "The Andes Mountains", "The Arctic"]'::jsonb,0,'Kush was a major African civilization that rivaled Egypt.','original'),
('113.51.c.1.A',3,'Mansa Musa of the Mali Empire became famous in the 1300s for doing what?','["Inventing the printing press", "Making a pilgrimage to Mecca with enormous amounts of gold", "Leading the Spanish conquest", "Founding Jamestown"]'::jsonb,1,'His wealth made Mali known across the world.','original'),
('113.51.c.1.B',3,'Which pre-colonial African institution was a center of learning in the city of Timbuktu?','["The Library of Congress", "Harvard", "The University of Sankore", "The Hull House"]'::jsonb,2,'Timbuktu was a center of scholarship.','original'),
('113.51.c.1.B',3,'The trans-Saharan trade linked West Africa to North Africa mainly through the exchange of what?','["Silk and tea", "Cotton and tobacco", "Oil and steel", "Gold and salt"]'::jsonb,3,'Caravans crossed the desert carrying goods.','original'),
('113.51.c.1.C',3,'Enslaved Africans were treated as property rather than people. This is an example of what?','["Dehumanization", "Assimilation", "Migration", "Emancipation"]'::jsonb,0,'Slavery denied the humanity of enslaved people.','original'),
('113.51.c.1.C',3,'Roughly how many Africans were forcibly carried across the Atlantic during the slave trade?','["About 12,000", "More than 12 million", "About 120,000", "About 1 million"]'::jsonb,1,'Millions were taken over four centuries.','original'),
('113.51.c.2.A',3,'The African diaspora refers to what?','["A type of music", "An ancient language", "The dispersal of African peoples and their descendants around the world", "A West African empire"]'::jsonb,2,'The slave trade created much of the diaspora.','original'),
('113.51.c.2.A',3,'European slave traders often obtained captives by doing what?','["Signing peace treaties", "Building universities", "Planting crops in Africa", "Trading goods for captives at coastal ports and forts"]'::jsonb,3,'Some African rulers and merchants took part in the trade.','original'),
('113.51.c.2.B',3,'Large sugar plantations in the Caribbean depended heavily on what?','["The labor of enslaved Africans", "Machines only", "Paid European tenants only", "Free workers only"]'::jsonb,0,'Sugar was extremely profitable and labor intensive.','original'),
('113.51.c.2.B',3,'Maroon communities in the Americas were formed by whom?','["Mexican generals", "Escaped enslaved people, sometimes allied with Native Americans", "Spanish priests", "European kings"]'::jsonb,1,'They were settlements of freedom.','original'),
('113.51.c.2.C',3,'The Middle Passage was what?','["A trade route in Asia", "A railroad", "The forced voyage across the Atlantic for captive Africans", "A mountain pass"]'::jsonb,2,'It was brutal and deadly.','original'),
('113.51.c.2.C',3,'The shared suffering of the Middle Passage led captives of different groups to do what?','["Forget all traditions", "Return home", "Speak a single African language only", "Create new common cultural forms and bonds"]'::jsonb,3,'New African American culture emerged.','original'),
('113.51.c.2.D',3,'Which factor encouraged the growth of slavery in the Southern colonies?','["Labor-intensive cash crops such as tobacco, rice and indigo", "Large factories", "A lack of land", "Cheap machines"]'::jsonb,0,'Plantations needed a large labor force.','original'),
('113.51.c.2.D',3,'The first documented Africans in English North America arrived at Jamestown in which year?','["1865", "1619", "1492", "1776"]'::jsonb,1,'They arrived in Virginia.','original'),
('113.51.c.3.A',3,'Which was an economic argument used to defend slavery after independence?','["That slavery would end soon", "That slavery was cheap for the North only", "That the cotton economy depended on enslaved labor", "That slaves paid taxes"]'::jsonb,2,'Economic interests were central to the defense of slavery.','original'),
('113.51.c.3.A',3,'Some slaveholders used religion to defend slavery by doing what?','["Freeing the enslaved", "Rejecting all religion", "Funding abolition", "Selectively citing scripture to justify the system"]'::jsonb,3,'This was one of several rationalizations.','original'),
('113.51.c.3.B',3,'The Three-Fifths Compromise counted each enslaved person as what?','["Three-fifths of a person for representation and taxation", "Two-thirds of a person", "A full citizen", "Zero persons"]'::jsonb,0,'It increased Southern political power.','original'),
('113.51.c.3.B',3,'The Fugitive Slave Act of 1850 required what?','["That fugitives be paid", "That people in free states help return escaped enslaved people", "That slavery end", "That Congress meet monthly"]'::jsonb,1,'It angered many Northerners.','original'),
('113.51.c.3.C ',3,'Disputes over slavery in new territories increased sectionalism because what?','["The territories were too small", "Everyone agreed", "The North and South disagreed about expanding slavery", "Slavery was banned"]'::jsonb,2,'The Missouri Compromise of 1820 tried to balance the sections.','original'),
('113.51.c.3.C ',3,'Which best describes sectionalism?','["Support for tariffs only", "Hatred of travel", "Loyalty to a political party", "Loyalty to one region''s interests over those of the nation"]'::jsonb,3,'Slavery deepened the divide between North and South.','original'),
('113.51.c.3.D',3,'Which event was a major armed rebellion by enslaved people in Virginia in 1831?','["Nat Turner''s Rebellion", "The Whiskey Rebellion", "The Boston Massacre", "Shays'' Rebellion"]'::jsonb,0,'It led to harsher slave codes.','original'),
('113.51.c.3.D',3,'The Underground Railroad helped enslaved people by doing what?','["Printing money", "Providing secret routes and safe houses to reach freedom", "Selling land", "Building trains"]'::jsonb,1,'Conductors such as Harriet Tubman guided many.','original'),
('113.51.c.3.E',3,'David Walker''s Appeal (1829) called on Black Americans to do what?','["Move to Europe", "Stay silent", "Resist slavery and demand freedom", "Support slavery"]'::jsonb,2,'It was a powerful abolitionist pamphlet.','original'),
('113.51.c.3.E',3,'Sojourner Truth is known as a speaker who did what?','["Invented the cotton gin", "Led the Confederate army", "Signed the Constitution", "Advocated for abolition and women''s rights"]'::jsonb,3,'She was formerly enslaved.','original'),
('113.51.c.3.F',3,'Great Britain abolished slavery throughout most of its empire in which year?','["1833", "1776", "1607", "1900"]'::jsonb,0,'The Slavery Abolition Act passed in 1833.','original'),
('113.51.c.3.F',3,'The U.S. ban on importing enslaved Africans took effect in which year?','["1776", "1808", "1861", "1920"]'::jsonb,1,'The Constitution allowed Congress to end the trade after 1808.','original'),
('113.51.c.4.A',3,'The 54th Massachusetts Infantry was significant because it was what?','["A Spanish colonial unit", "A Confederate unit", "One of the first Black regiments to fight in the Civil War", "A World War I unit"]'::jsonb,2,'Its attack on Fort Wagner showed Black soldiers'' courage.','original'),
('113.51.c.4.A',3,'Harriet Tubman served the Union during the Civil War as what?','["A newspaper owner", "A senator", "A Confederate general", "A scout, nurse and spy"]'::jsonb,3,'She guided the Combahee River Raid.','original'),
('113.51.c.4.B',3,'A success of Reconstruction was what?','["The passage of the 13th, 14th and 15th Amendments", "The end of racism", "Equal wages", "Land for all freedpeople"]'::jsonb,0,'The amendments extended rights.','original'),
('113.51.c.4.B',3,'A failure of Reconstruction was that it did what?','["Gave land to all", "Ended in 1877 with federal troops withdrawn and rights eroded", "Created integrated schools nationwide", "Banned the KKK permanently"]'::jsonb,1,'Southern governments rolled back gains.','original'),
('113.51.c.4.C ',3,'Booker T. Washington''s Atlanta Compromise speech urged Black Americans to do what?','["Reject education", "Demand immediate full equality", "Focus on vocational training and economic progress", "Return to Africa"]'::jsonb,2,'Du Bois disagreed with this approach.','original'),
('113.51.c.4.C ',3,'Ida B. Wells became known for doing what?','["Leading troops", "Founding Tuskegee", "Writing the 14th Amendment", "Investigating and writing against lynching"]'::jsonb,3,'She was a journalist and activist.','original'),
('113.51.c.4.D',3,'The Colfax Massacre of 1873 occurred in which state?','["Louisiana", "Oregon", "Maine", "Ohio"]'::jsonb,0,'Dozens of Black men were killed in a political dispute.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_aas_v1'
from (values
('113.51.c.4.D',3,'The Camp Logan Mutiny of 1917 took place in which Texas city?','["El Paso", "Houston", "Austin", "Dallas"]'::jsonb,1,'Black soldiers clashed after police abuse.','original'),
('113.51.c.4.E',3,'The convict leasing system allowed states to do what?','["Close prisons", "Pay prisoners high wages", "Lease prisoners to private businesses for labor", "Free prisoners"]'::jsonb,2,'It often replaced slavery''s labor in practice.','original'),
('113.51.c.4.E',3,'In 2018, remains found in Sugar Land, Texas, were identified as those of whom?','["Railroad workers", "Civil War soldiers", "Spanish settlers", "Black convict laborers known as the Sugar Land 95"]'::jsonb,3,'They were leased convicts who died in the 1800s.','original'),
('113.51.c.4.F',3,'Jim Crow laws required what?','["Separation of Black and white people in public life", "Integrated housing", "Equal schools for all", "Voting rights for all"]'::jsonb,0,'They enforced segregation.','original'),
('113.51.c.4.F',3,'Literacy tests and poll taxes were used to do what?','["Reduce taxes", "Keep Black citizens from voting", "Register all voters", "Raise school funds"]'::jsonb,1,'They were tools of disfranchisement.','original'),
('113.51.c.4.G',3,'Plessy v. Ferguson (1896) upheld what doctrine?','["Equal protection for all", "One person, one vote", "Separate but equal", "Freedom of the press"]'::jsonb,2,'It allowed legal segregation.','original'),
('113.51.c.4.G',3,'Plessy v. Ferguson was later overturned in public education by what case?','["Marbury v. Madison", "Dred Scott v. Sandford", "Gideon v. Wainwright", "Brown v. Board of Education"]'::jsonb,3,'Brown was decided in 1954.','original'),
('113.51.c.4.H',3,'Which organization, founded in 1909, fought segregation through the courts?','["The NAACP", "The Federal Reserve", "The Confederate Army", "The Ku Klux Klan"]'::jsonb,0,'W. E. B. Du Bois helped found it.','original'),
('113.51.c.4.H',3,'The Great Migration was a response to Jim Crow because many Black Southerners chose to do what?','["Join the army", "Move to Northern and Western cities for jobs and safety", "Stay on farms", "Move to Mexico"]'::jsonb,1,'They sought opportunity.','original'),
('113.51.c.4.I',3,'The 369th Infantry, known as the Harlem Hellfighters, did what in World War I?','["Refused to fight", "Guarded prisoners only", "Fought with French forces and earned honors", "Served only in the U.S."]'::jsonb,2,'They were praised for bravery.','original'),
('113.51.c.4.I',3,'After World War I, many Black veterans returned to what?','["Free land", "Full equality", "A hero''s welcome everywhere", "Continued discrimination and violence at home"]'::jsonb,3,'The Red Summer of 1919 saw racial violence.','original'),
('113.51.c.4.J',3,'The Buffalo Soldiers were what?','["Black regiments of the U.S. Army that served after the Civil War", "A baseball team", "A farm union", "Confederate spies"]'::jsonb,0,'They served on the western frontier.','original'),
('113.51.c.4.J',3,'Which units were Buffalo Soldier cavalry regiments?','["The 761st Tank Battalion", "The 9th and 10th Cavalry", "The 54th and 55th Infantry", "The 1st and 2nd Marines"]'::jsonb,1,'They also included the 24th and 25th Infantry.','original'),
('113.51.c.5.A',3,'A negative effect of the Great Depression on African Americans was that they often what?','["Gained wealth", "Lost no jobs", "Faced higher unemployment than white workers", "Left the country"]'::jsonb,2,'They were often the last hired and first fired.','original'),
('113.51.c.5.A',3,'A positive effect of the New Deal on many African Americans was what?','["Guaranteed equal pay", "The end of segregation", "Free land", "Jobs through programs such as the WPA and CCC"]'::jsonb,3,'Yet many programs discriminated.','original'),
('113.51.c.5.B',3,'Sweatt v. Painter (1950) concerned what?','["A Black applicant denied admission to the University of Texas Law School", "Fair housing", "A bus boycott", "Voting rights"]'::jsonb,0,'The Court found the separate school unequal.','original'),
('113.51.c.5.B',3,'Brown v. Board of Education (1954) ruled that what was unconstitutional?','["Taxes", "Segregation in public schools", "Voting by mail", "School prayer"]'::jsonb,1,'The Court said separate was inherently unequal.','original'),
('113.51.c.5.C',3,'Rosa Parks'' refusal to give up her bus seat in 1955 helped start what?','["The Great Migration", "The March on Washington", "The Montgomery Bus Boycott", "The Civil War"]'::jsonb,2,'The boycott lasted over a year.','original'),
('113.51.c.5.C',3,'The Little Rock Nine were students who did what?','["Founded the NAACP", "Founded Tuskegee", "Led a bus boycott", "Integrated Central High School in Arkansas in 1957"]'::jsonb,3,'Daisy Bates mentored them.','original'),
('113.51.c.5.D',3,'Leaders of the U.S. civil rights movement drew inspiration from independence movements in what?','["Africa and India", "Antarctica", "Greenland", "Australia"]'::jsonb,0,'Examples include Ghana and Gandhi''s nonviolence.','original'),
('113.51.c.5.D',3,'Pan-Africanism emphasized what?','["Segregation", "Unity among people of African descent worldwide", "Isolation", "Colonial rule"]'::jsonb,1,'It connected diaspora struggles.','original'),
('113.51.c.5.E',3,'During World War II, the U.S. armed forces were what?','["Reserved for whites only by law", "Fully integrated", "Segregated by race", "Closed to women"]'::jsonb,2,'Black soldiers often served in separate units.','original'),
('113.51.c.5.E',3,'The "Double V" campaign called for victory over what?','["Two football teams", "Two nations", "Two political parties", "Fascism abroad and racism at home"]'::jsonb,3,'It was promoted by the Pittsburgh Courier.','original'),
('113.51.c.5.F',3,'Doris "Dorie" Miller received the Navy Cross for his actions at what event?','["Pearl Harbor", "The Battle of Gettysburg", "Iwo Jima", "D-Day"]'::jsonb,0,'He manned an anti-aircraft gun.','original'),
('113.51.c.5.F',3,'The Tuskegee Airmen were the first what?','["Astronauts", "Black military pilots in the U.S. Army Air Forces", "Marines", "Navy admirals"]'::jsonb,1,'They trained in Alabama.','original'),
('113.51.c.5.G ',3,'Executive Order 9981 (1948) did what?','["Ended school segregation", "Banned poll taxes", "Ordered the desegregation of the U.S. armed forces", "Created Medicare"]'::jsonb,2,'President Truman signed it.','original'),
('113.51.c.5.G ',3,'A. Philip Randolph is known for threatening what in 1941?','["A boycott of baseball", "A tax revolt", "A general strike by soldiers", "A march on Washington to protest discrimination in defense jobs"]'::jsonb,3,'President Roosevelt issued an order banning discrimination in defense industries.','original'),
('113.51.c.5.H',3,'Sit-ins at lunch counters, beginning in Greensboro in 1960, were what?','["Nonviolent protests against segregated service", "Court cases", "Tax strikes", "Military operations"]'::jsonb,0,'They spread across the South.','original'),
('113.51.c.5.H',3,'The Voting Rights Act of 1965 was a success because it did what?','["Banned unions", "Outlawed practices that kept Black citizens from voting", "Created Social Security", "Ended school segregation"]'::jsonb,1,'Black voter registration rose sharply.','original'),
('113.51.c.5.I',3,'One way the Civil Rights Movement transformed American politics was by doing what?','["Eliminating elections", "Ending all inequality", "Increasing Black voting and the number of Black elected officials", "Abolishing political parties"]'::jsonb,2,'Gains were significant but incomplete.','original'),
('113.51.c.5.I',3,'A limit on the Civil Rights Movement''s success is that what remained?','["Segregation laws everywhere", "No Black elected officials", "No Black voters", "Disparities in wealth, housing and education"]'::jsonb,3,'Evaluating success includes ongoing gaps.','original'),
('113.51.c.6.A',3,'Which is an issue in the continuing effort to achieve equality?','["Unequal access to housing, health care and education", "Equal wealth", "Perfect equality", "A lack of jobs for everyone"]'::jsonb,0,'Gaps persist.','original'),
('113.51.c.6.A',3,'Voting rights remain an issue because of debates over what?','["Whether voting exists", "Voter identification and access to polling places", "Tax rates", "School lunches"]'::jsonb,1,'Policies affect participation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
