from (values
('113.51.c.13.D',3,'Hip hop began in the 1970s in which borough?','["The Bronx in New York City", "Seattle", "Miami", "Houston"]'::jsonb,0,'DJ Kool Herc is credited with early development.','original'),
('113.51.c.13.E',3,'The Fisk Jubilee Singers raised money for their school by doing what?','["Building railroads", "Touring and performing spirituals for national and international audiences", "Running a bank", "Selling land"]'::jsonb,1,'They helped save Fisk University.','original'),
('113.51.c.13.E',3,'The Fisk Jubilee Singers'' tours helped do what?','["Create jazz", "End the Civil War", "Introduce spirituals to a worldwide audience", "Win suffrage"]'::jsonb,2,'They sang for Queen Victoria.','original'),
('113.51.c.14.A',3,'Scott Joplin is best known for composing what style?','["Country", "Hip hop", "Opera only", "Ragtime, including the Maple Leaf Rag"]'::jsonb,3,'He was the King of Ragtime.','original'),
('113.51.c.14.A',3,'James Reese Europe was a bandleader who did what?','["Directed the 369th Infantry band and helped bring jazz to Europe", "Wrote hip hop", "Invented the piano", "Founded Motown"]'::jsonb,0,'He influenced early jazz.','original'),
('113.51.c.14.B',3,'Katherine Dunham was a pioneer who did what?','["Won an Oscar", "Combined dance and anthropology to bring African and Caribbean dance to the stage", "Invented ballet", "Led an army"]'::jsonb,1,'She founded a major dance company.','original'),
('113.51.c.14.B',3,'The Dance Theatre of Harlem, founded in 1969, was created by whom?','["Alvin Ailey", "Duke Ellington", "Arthur Mitchell", "Langston Hughes"]'::jsonb,2,'He was the first Black principal dancer with New York City Ballet.','original'),
('113.51.c.14.C ',3,'The Harlem Renaissance was a flowering of what in the 1920s?','["A trade union", "A military campaign", "A political party", "Black art, literature and music centered in Harlem"]'::jsonb,3,'It celebrated Black identity.','original'),
('113.51.c.14.C ',3,'Langston Hughes was a leading figure of the Harlem Renaissance as a what?','["Poet", "General", "Senator", "Inventor"]'::jsonb,0,'His poetry captured Black life.','original'),
('113.51.c.14.D ',3,'W. E. B. Du Bois''s The Souls of Black Folk introduced the idea of what?','["Laissez-faire", "Double consciousness", "Manifest destiny", "Separate but equal"]'::jsonb,1,'It described seeing oneself through others'' eyes.','original'),
('113.51.c.14.D ',3,'Toni Morrison won the 1988 Pulitzer Prize for which novel?','["Invisible Man", "Native Son", "Beloved", "Roots"]'::jsonb,2,'It explores the legacy of slavery.','original'),
('113.51.c.14.E ',3,'Oscar Micheaux was a pioneer who did what?','["Invented television", "Wrote the Constitution", "Led a union", "Produced and directed early films by and about Black Americans"]'::jsonb,3,'He made dozens of films.','original'),
('113.51.c.14.E ',3,'Lorraine Hansberry''s A Raisin in the Sun was the first play by a Black woman to do what?','["Be produced on Broadway", "Be filmed in 1900", "Win a Nobel Prize", "Be banned in 1959"]'::jsonb,0,'It premiered in 1959.','original'),
('113.51.c.14.F',3,'Jacob Lawrence''s Migration Series is a work of what?','["A treaty", "Visual art depicting the Great Migration", "A court case", "A symphony"]'::jsonb,1,'It used paintings to tell history.','original'),
('113.51.c.14.F',3,'Gospel music grew from what tradition?','["Classical opera", "Disco", "African American church music and spirituals", "Polka"]'::jsonb,2,'It influenced soul and R&B.','original'),
('113.51.c.14.G',3,'Minstrel shows in the 1800s harmed African Americans by doing what?','["Raising wages", "Ending prejudice", "Honoring them", "Spreading demeaning stereotypes"]'::jsonb,3,'They were a form of popular entertainment.','original'),
('113.51.c.14.G',3,'Motown Records, founded in 1959, helped Black artists do what?','["Reach mainstream audiences across racial lines", "Avoid radio", "Leave the country", "Stop recording"]'::jsonb,0,'Artists included the Supremes and Stevie Wonder.','original'),
('113.51.c.15.A ',3,'Anti-literacy laws in many Southern states did what?','["Required schooling", "Made it illegal to teach enslaved people to read and write", "Funded schools", "Ended slavery"]'::jsonb,1,'They tried to keep the enslaved from learning.','original'),
('113.51.c.15.A ',3,'Frederick Douglass described learning to read as what?','["Unimportant", "A punishment", "A path toward freedom", "Easy to get"]'::jsonb,2,'He learned in secret.','original'),
('113.51.c.15.B',3,'Rosenwald Schools were built through a partnership of whom?','["John D. Rockefeller", "Thomas Jefferson", "Abraham Lincoln", "Julius Rosenwald and Booker T. Washington''s Tuskegee Institute"]'::jsonb,3,'They built thousands of rural schools for Black children.','original'),
('113.51.c.15.B',3,'The Second Morrill Act (1890) helped create what?','["Land-grant colleges for Black students", "Interstate highways", "Public libraries", "Medicare"]'::jsonb,0,'Many HBCUs were established or funded.','original'),
('113.51.c.15.C',3,'The school-to-prison pipeline refers to what?','["A sports league", "Policies that push students out of school and toward the justice system", "A school bus route", "A career program"]'::jsonb,1,'It disproportionately affects Black students.','original'),
('113.51.c.15.C',3,'An opportunity gap in education means what?','["Different school colors", "Differences in height", "Unequal access to resources that affect student achievement", "Different mascots"]'::jsonb,2,'It differs from an achievement gap.','original'),
('113.51.c.16.A ',3,'African civilizations contributed to science and technology through what?','["Only warfare", "Only farming", "Only trade", "Advances in astronomy, mathematics and architecture"]'::jsonb,3,'Examples include Egyptian pyramids and Timbuktu manuscripts.','original'),
('113.51.c.16.A ',3,'Great Zimbabwe is notable for what?','["Massive stone architecture built by an African civilization", "Wooden forts", "Glass skyscrapers", "Underground tunnels"]'::jsonb,0,'It reflects advanced engineering.','original'),
('113.51.c.16.B',3,'Jan Matzeliger''s shoe-lasting machine helped industrialization by doing what?','["Increasing prices only", "Speeding up shoe manufacturing", "Ending factories", "Slowing production"]'::jsonb,1,'It transformed shoemaking.','original'),
('113.51.c.16.B',3,'Elijah McCoy invented a device that did what?','["Made ice", "Cleaned carpets", "Automatically lubricated engines", "Cooked food"]'::jsonb,2,'It reduced downtime for machines.','original'),
('113.51.c.16.C',3,'George Washington Carver promoted what agricultural practice?','["Cotton monoculture", "Overgrazing", "Slash and burn", "Crop rotation and peanuts to restore soil"]'::jsonb,3,'He worked at Tuskegee.','original'),
('113.51.c.16.C',3,'Katherine Johnson''s calculations helped NASA do what?','["Plan orbital flights, including John Glenn''s", "Build ships", "Dig tunnels", "Write laws"]'::jsonb,0,'She was a mathematician.','original'),
('113.51.c.17.A',3,'Which of these is a primary source for studying the Civil Rights Movement?','["An encyclopedia", "Dr. King''s \"I Have a Dream\" speech", "A modern textbook", "A later documentary"]'::jsonb,1,'Primary sources are from the time.','original'),
('113.51.c.17.A',3,'A migration map showing movement from Mississippi to Chicago helps a student do what?','["Learn a language", "Find a river''s depth", "See patterns of the Great Migration", "Measure temperature"]'::jsonb,2,'Maps reveal geographic patterns.','original'),
('113.51.c.17.B',3,'Placing the Emancipation Proclamation, the 13th Amendment and Plessy v. Ferguson in order is what skill?','["Making a generalization", "Finding bias", "Reading a legend", "Applying chronology through sequencing"]'::jsonb,3,'They occurred in 1863, 1865 and 1896.','original'),
('113.51.c.17.B',3,'Explaining how cotton demand led to more enslaved labor shows what skill?','["Identifying cause and effect", "Mapping", "Paraphrasing", "Memorizing"]'::jsonb,0,'Cause and effect connect events.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
