from (values
('113.51.c.17.C',3,'Historical inquiry begins when a student does what?','["Skips research", "Poses a question and gathers multiple sources", "States a conclusion", "Copies a text"]'::jsonb,1,'Evidence guides interpretation.','original'),
('113.51.c.17.C',3,'A student studying the Great Migration should use which kinds of evidence?','["Only opinions", "Only rumors", "Census data, letters and newspaper articles", "Only one letter"]'::jsonb,2,'Multiple sources give a fuller picture.','original'),
('113.51.c.17.D',3,'Two sources agreeing about the date of the Tulsa Race Massacre is an example of what?','["Sequencing", "Bias", "Plagiarism", "Corroboration"]'::jsonb,3,'Agreement supports validity.','original'),
('113.51.c.17.D',3,'A newspaper account written by a participant in a protest may be limited by what?','["The author''s point of view and frame of reference", "Its price", "Its page count", "Its font size"]'::jsonb,0,'Evaluate author''s perspective.','original'),
('113.51.c.17.E',3,'A pro-segregation editorial from 1900 would likely show what?','["A modern view", "Bias supporting the writer''s point of view", "Neutral facts", "A scientific proof"]'::jsonb,1,'Identify bias and support with evidence.','original'),
('113.51.c.17.E',3,'A historian identifies bias in a source by looking for what?','["Page numbers", "Footnotes", "Loaded language and one-sided claims", "Photographs"]'::jsonb,2,'Language reveals perspective.','original'),
('113.51.c.18.A',3,'A researcher quotes a speech from 1963 in a paper. What must be done?','["Change the words", "Remove the quote", "Claim it as original", "Provide a citation to the source"]'::jsonb,3,'Citing avoids plagiarism.','original'),
('113.51.c.18.A',3,'A good oral presentation on the Harlem Renaissance includes what?','["Clear organization, evidence and visuals", "Reading without looking up", "No sources", "Only opinions"]'::jsonb,0,'Communication skills matter.','original'),
('113.51.c.18.B ',3,'Using the term "suffrage" correctly means referring to what?','["A type of tax", "The right to vote", "The right to travel", "A kind of law"]'::jsonb,1,'Accurate terminology is key.','original'),
('113.51.c.18.B ',3,'Which term means the separation of groups by race?','["Migration", "Assimilation", "Segregation", "Integration"]'::jsonb,2,'Terms must match concepts.','original'),
('113.51.c.19.A',3,'A thematic map of the Great Migration would best show what?','["Population density only", "Climate zones", "Mountain heights", "The routes and destinations of migrants"]'::jsonb,3,'Maps display patterns.','original'),
('113.51.c.19.A',3,'A line graph of Black voter registration in Mississippi from 1960 to 1970 would show what?','["A change in registration over time", "Rainfall", "Temperature", "Religion"]'::jsonb,0,'Graphs show trends.','original'),
('113.51.c.19.B',3,'A map shows that most Black Southerners moved to Chicago, Detroit and New York. What question could a student pose?','["How tall are the cities?", "Why did these cities attract so many migrants?", "What is the capital of Texas?", "What color is the map?"]'::jsonb,1,'Questions guide analysis of patterns.','original'),
('113.51.c.19.B',3,'A student reads a chart of HBCU enrollment. Which question is best?','["What is its color?", "What is the font?", "How has enrollment changed since 1970 and why?", "Who drew the chart?"]'::jsonb,2,'Ask analytical questions.','original'),
('113.51.c.20',3,'A school community faces a gap in resources between two campuses. What is the first step in a problem-solving process?','["Skip to funding", "Announce a decision", "Evaluate the final result", "Identify and define the problem"]'::jsonb,3,'Define the problem first.','original'),
('113.51.c.20',3,'After gathering information about the resource gap, a group should do what?','["List and consider possible solutions", "Ignore the facts", "Delete the data", "Stop the project"]'::jsonb,0,'Consider options before deciding.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
